public class Main {
  static boolean isPalindrome(String s) {
    int i = 0, j = s.length() - 1;
    while (i < j) {
      if (s.charAt(i++) != s.charAt(j--)) return false;
    }
    return true;
  }

  public static void main(String[] args) {
    System.out.println(isPalindrome("racecar"));
  }
}

